import{_ as a,c as r,o as t,ag as n}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Virtual Environments","description":"","frontmatter":{"title":"Virtual Environments"},"headers":[],"relativePath":"general/virtual-environments.md","filePath":"general/virtual-environments.md","lastUpdated":null}'),i={name:"general/virtual-environments.md"};function o(s,e,l,p,h,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="virtual-environments" tabindex="-1">Virtual Environments <a class="header-anchor" href="#virtual-environments" aria-label="Permalink to &quot;Virtual Environments&quot;">​</a></h1><h2 id="virtual-environments-1" tabindex="-1">Virtual Environments <a class="header-anchor" href="#virtual-environments-1" aria-label="Permalink to &quot;Virtual Environments&quot;">​</a></h2><h3 id="hypervisors" tabindex="-1">Hypervisors <a class="header-anchor" href="#hypervisors" aria-label="Permalink to &quot;Hypervisors&quot;">​</a></h3><p>Hypervisors are the software, firmware, or hardware that create and run virtual machines. They come in two types:</p><ul><li><p><strong>Type 1 Hypervisors:</strong> Also known as bare-metal hypervisors, they run directly on the host’s hardware to manage guest operating systems. Examples include VMware ESXi, Microsoft Hyper-V, and Xen.</p></li><li><p><strong>Type 2 Hypervisors:</strong> These run on a host operating system and provide virtualization services. Examples include VMware Workstation, Oracle VM VirtualBox, and Parallels Desktop.</p></li></ul><h3 id="virtual-machines-vms" tabindex="-1">Virtual Machines (VMs) <a class="header-anchor" href="#virtual-machines-vms" aria-label="Permalink to &quot;Virtual Machines (VMs)&quot;">​</a></h3><h3 id="what-is-a-vm" tabindex="-1">What is a VM? <a class="header-anchor" href="#what-is-a-vm" aria-label="Permalink to &quot;What is a VM?&quot;">​</a></h3><p>A Virtual Machine (VM) is a software-based computer system emulation. VMs provide the functionality of a physical computer, but they run as a process on a host machine. VMs are essential for isolating and containing vulnerabilities, as they provide a separate environment for running applications without affecting the host system.</p><h3 id="why-use-a-vm" tabindex="-1">Why Use a VM? <a class="header-anchor" href="#why-use-a-vm" aria-label="Permalink to &quot;Why Use a VM?&quot;">​</a></h3><ul><li><p><strong>Isolation:</strong> VMs allow you to run applications in a contained environment, reducing the risk of system-wide vulnerabilities.</p></li><li><p><strong>Testing and Development:</strong> VMs are ideal for testing new software or operating systems without additional hardware.</p></li><li><p><strong>Resource Optimization:</strong> Multiple VMs can run on a single physical machine, efficiently using hardware resources.</p></li></ul><h3 id="virtual-environment-options" tabindex="-1">Virtual Environment Options <a class="header-anchor" href="#virtual-environment-options" aria-label="Permalink to &quot;Virtual Environment Options&quot;">​</a></h3><ul><li><p>**[A free, open-source virtualization product for enterprise and home use.</p></li><li><p><strong><a href="/general/virtualbox-guide.html">VMware</a>:</strong>)(/vmware)😗* A popular virtualization platform offering both free and commercial products.</p></li><li><p><strong>UTM (MacOS Only):</strong> A simple VM management tool for macOS. <a href="https://mac.getutm.app" target="_blank" rel="noreferrer">here</a></p></li><li><p><strong>Parallels (MacOS Only):</strong> A commercial solution for running Windows on Mac.</p></li><li><p><strong>Bare Metal (Type 1 Hypervisor):</strong> For direct installation on hardware. See <a href="/general/booting-os-from-usb.html">to Flash ISO to Hardware</a></p></li><li><p><strong>Docker:</strong> A tool designed to make creating, deploying, and running container applications easier.</p></li><li><p><strong><a href="/research/research-containers.html">Containers for research</a></strong></p></li><li><p><strong><a href="/general/android-virtual-device.html">Virtual Device (AVD) Emulator</a>:</strong> A tool for running and debugging Android applications. It is part of Android Studio and offers a free and open-source solution for Android development.</p></li></ul><hr><h3 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h3><ul><li><p><a href="/general/vmware.html">* Docker Containers for research</a></p></li><li><p><a href="/general/dfp-guide.html">Guide</a></p></li></ul><p>[Machines]</p><p>[Systems]</p>',17)])])}const c=a(i,[["render",o]]);export{m as __pageData,c as default};
